const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),radar=document.getElementById('radar'),rctx=radar.getContext('2d');
let W=innerWidth,H=innerHeight,DPR=1,active=false,paused=false,remaining=300,countdown=0,last=0,elapsed=0,shake=0;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),hyp=(x,z)=>Math.hypot(x,z);
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0);radar.width=radar.clientWidth*DPR;radar.height=radar.clientHeight*DPR;rctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
const keys=new Set(),pads=[];for(let z=-42;z<=42;z+=14)for(const x of [-27,-14,0,14,27])if(Math.random()>.25)pads.push({x,z,charge:0});
const player={x:0,y:0,z:-23,vx:0,vy:0,vz:0,yaw:0,boost:100,air:0,flip:0,team:'blue',isPlayer:true};
const bots=[{x:-7,y:0,z:13,yaw:Math.PI,team:'orange',boost:70},{x:8,y:0,z:20,yaw:Math.PI,team:'orange',boost:60},{x:11,y:0,z:-8,yaw:0,team:'blue',boost:50}].map(o=>({...o,vx:0,vy:0,vz:0,brain:0}));
const ball={x:0,y:2.6,z:0,vx:0,vy:0,vz:0,r:2.05};let blueGoals=0,orangeGoals=0,goalTimer=0,particles=[],boostBursts=[];
function proj(x,y,z){const c=cam,dx=x-c.x,dy=y-c.y,dz=z-c.z;const side=dx*c.rx+dz*c.rz,depth=dx*c.fx+dy*c.fy+dz*c.fz,up=dx*c.ux+dy*c.uy+dz*c.uz;const f=Math.min(W,H)*.94,dd=Math.max(.08,depth);return {x:W*.5+side*f/dd,y:H*.48-up*f/dd,d:depth,s:f/dd}}
let cam={};function updateCam(){const fwd={x:Math.sin(player.yaw),z:Math.cos(player.yaw)};const tx=player.x+fwd.x*4,ty=player.y+1.3,tz=player.z+fwd.z*4;cam.x=player.x-fwd.x*10;cam.y=player.y+6.2;cam.z=player.z-fwd.z*10;let fx=tx-cam.x,fy=ty-cam.y,fz=tz-cam.z,l=Math.hypot(fx,fy,fz);cam.fx=fx/l;cam.fy=fy/l;cam.fz=fz/l;let rl=Math.hypot(cam.fx,cam.fz);cam.rx=cam.fz/rl;cam.rz=-cam.fx/rl;cam.ux=cam.ry=0;cam.ux=-cam.fx*cam.fy/rl;cam.uy=rl;cam.uz=-cam.fz*cam.fy/rl}
function path3(points,color,width=2,close=false){ctx.beginPath();let n=0;for(const p of points){const q=proj(p[0],p[1],p[2]);if(q.d<=.2){n=0;continue}if(!n)ctx.moveTo(q.x,q.y);else ctx.lineTo(q.x,q.y);n++}if(close)ctx.closePath();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
function fill3(points,color,stroke=null,width=1){const q=points.map(p=>proj(...p));if(q.some(a=>a.d<=.2))return;ctx.beginPath();ctx.moveTo(q[0].x,q[0].y);for(let i=1;i<q.length;i++)ctx.lineTo(q[i].x,q[i].y);ctx.closePath();ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()}}
function line3(a,b,color,width=1){path3([a,b],color,width)}
function drawSky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#071323');g.addColorStop(.52,'#172d44');g.addColorStop(1,'#243b4a');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);const glow=ctx.createRadialGradient(W*.5,H*.28,4,W*.5,H*.3,H*.62);glow.addColorStop(0,'#51b7d52b');glow.addColorStop(1,'#0a142000');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);for(const sx of [.08,.28,.72,.92]){ctx.fillStyle='#ddf8ff';ctx.shadowColor='#88deff';ctx.shadowBlur=22;ctx.beginPath();ctx.ellipse(W*sx,H*.18,20,5,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}}
function drawArena(){
// Full pitch and alternating turf bands
fill3([[-39,0,-55],[39,0,-55],[39,0,55],[-39,0,55]],'#1b574b');
for(let z=-55;z<55;z+=11)fill3([[-39,.012,z],[39,.012,z],[39,.012,z+5.5],[-39,.012,z+5.5]],'#ffffff08');
// stadium bowl, curved side ramps
for(const sign of [-1,1]){for(let i=0;i<8;i++){const x0=39+i*1.35,x1=x0+1.35,y0=Math.max(0,Math.pow(i/7,1.8)*14),y1=Math.max(0,Math.pow((i+1)/7,1.8)*14);fill3([[sign*x0,y0,-57],[sign*x1,y1,-57],[sign*x1,y1,57],[sign*x0,y0,57]],i%2?'#253949':'#304456');}fill3([[sign*39,0,-55],[sign*49,15,-55],[sign*49,15,55],[sign*39,0,55]],'#112538');}
// end terraces
for(const sign of [-1,1]){fill3([[-39,0,sign*55],[39,0,sign*55],[39,14,sign*58],[-39,14,sign*58]],'#243a4b');for(let y=2;y<13;y+=2.5)line3([-38,y,sign*57],[38,y,sign*57],'#7da0b244',1)}
// pitch paint
const white='#d9f3e7b9';line3([-38,.06,-54],[38,.06,-54],white,2);line3([-38,.06,54],[38,.06,54],white,2);line3([-38,.06,-54],[-38,.06,54],white,2);line3([38,.06,-54],[38,.06,54],white,2);line3([0,.07,-54],[0,.07,54],'#effff2c9',2);
for(let a=0;a<64;a++){const t=a/64*Math.PI*2;line3([Math.cos(t)*8,.08,Math.sin(t)*8],[Math.cos((a+1)/64*Math.PI*2)*8,.08,Math.sin((a+1)/64*Math.PI*2)*8],white,2)}
for(const z of [-38,38]){for(let a=0;a<48;a++){let t=a/48*Math.PI*2;line3([Math.cos(t)*13,.05,z+Math.sin(t)*13],[Math.cos((a+1)/48*Math.PI*2)*13,.05,z+Math.sin((a+1)/48*Math.PI*2)*13],white,1.5)}line3([-18,.05,z],[18,.05,z],white,1.5);line3([-18,.05,z],[ -18,.05,z+Math.sign(z)*14],white,1.5);line3([18,.05,z],[18,.05,z+Math.sign(z)*14],white,1.5)}
// goal frames, mesh nets and neon rims
for(const sign of [-1,1]){const gz=sign*54,c=sign<0?'#29aaff':'#ff793b';for(const x of [-10,10])line3([x,0,gz],[x,7.5,gz],c,5);line3([-10,7.5,gz],[10,7.5,gz],c,5);line3([-10,0,gz],[10,0,gz],c,3);for(let x=-9;x<=9;x+=3)line3([x,0,gz],[x,6,gz+sign*7],'#9ddfff32',1);for(let y=1;y<7;y+=1.5)line3([-10,y,gz],[10,y,gz],'#9ddfff30',1);ctx.shadowColor=c;ctx.shadowBlur=22;for(const x of [-10,10]){let p=proj(x,7.5,gz);ctx.fillStyle=c;ctx.beginPath();ctx.arc(p.x,p.y,5,0,7);ctx.fill()}ctx.shadowBlur=0}
// boundary neon edge
for(const sign of [-1,1])line3([sign*39,.12,-54],[sign*39,.12,54],sign>0?'#ff96574c':'#43caff4c',3);
// crowd tiers: tiny colorful spectators in seating banks
for(let side of [-1,1])for(let row=0;row<5;row++){const x=side*(41+row*1.1),y=2.2+row*1.9;for(let z=-48;z<=48;z+=1.15){if(Math.random()>.93)continue;const p=proj(x,y+rand(-.15,.22),z+rand(-.25,.25));if(p.d<2)continue;ctx.fillStyle=['#e9b65b','#8ad2dc','#d47e91','#9daee2','#e8e4d7'][Math.floor(Math.random()*5)];ctx.globalAlpha=.35+Math.random()*.45;ctx.fillRect(p.x,p.y,Math.max(1,p.s*.24),Math.max(1,p.s*.3));ctx.globalAlpha=1}}
// glowing sideline boards
for(let side of [-1,1]){const c=side<0?'#35bfff':'#ff8742';fill3([[side*39,.3,-52],[side*39,1.6,-52],[side*39,1.6,52],[side*39,.3,52]],'#0d2435',c,1.5);for(let z=-47;z<50;z+=10)line3([side*39,.65,z],[side*39,.65,z+4],c,2)}
// boost pads
for(const p of pads){const a=proj(p.x,.08,p.z);if(a.d<2)continue;const rad=Math.max(2,a.s*(p.charge>0?1.05:.65));ctx.save();ctx.translate(a.x,a.y);ctx.rotate(.2);ctx.fillStyle=p.charge>0?'#ff8b38':'#a85e347d';ctx.shadowColor='#ff813b';ctx.shadowBlur=p.charge>0?18:6;ctx.beginPath();ctx.ellipse(0,0,rad,rad*.48,0,0,7);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#ffd185';ctx.lineWidth=Math.max(1,a.s*.06);ctx.beginPath();ctx.ellipse(0,0,rad*.64,rad*.3,0,0,7);ctx.stroke();ctx.restore()}
}

