function carPoint(car,lx,ly,lz){const cs=Math.cos(car.yaw),sn=Math.sin(car.yaw);return [car.x+cs*lx+sn*lz,car.y+ly,car.z-sn*lx+cs*lz]}
function drawCar(car){const boost=car.isPlayer?keys.has('shift')&&car.boost>0:hyp(car.vx,car.vz)>17;const color=car.team==='blue'?'#38b9f4':'#ff793b',lit=car.team==='blue'?'#a1f2ff':'#ffd09d';
// ground shadow and exhaust
const sh=proj(car.x,.05,car.z);if(sh.d>1){ctx.fillStyle='#02091088';ctx.beginPath();ctx.ellipse(sh.x,sh.y,Math.max(3,sh.s*2.15),Math.max(2,sh.s*.7),0,0,Math.PI*2);ctx.fill()}
if(boost){for(let i=0;i<2;i++){const p=carPoint(car,(i?-.55:.55),.55,-2.5),q=proj(...p);if(q.d>1){const size=Math.max(2,q.s*rand(.32,.68));const gr=ctx.createRadialGradient(q.x,q.y,0,q.x,q.y,size*2.7);gr.addColorStop(0,'#fff6b8');gr.addColorStop(.28,car.team==='blue'?'#4ce8ff':'#ffb04e');gr.addColorStop(1,'#ff553000');ctx.fillStyle=gr;ctx.beginPath();ctx.ellipse(q.x,q.y,size*2.7,size,0,0,7);ctx.fill()}}}
// four chunky wheels
for(const sx of [-1,1])for(const sz of [-1,1]){const p=carPoint(car,sx*1.35,.55,sz*1.35),q=proj(...p),r=Math.max(2,q.s*.55);if(q.d<.2)continue;ctx.fillStyle='#07111a';ctx.beginPath();ctx.ellipse(q.x,q.y,r,r*1.12,.08,0,7);ctx.fill();ctx.strokeStyle='#455a69';ctx.lineWidth=Math.max(1,r*.14);ctx.stroke();ctx.fillStyle='#8194a0';ctx.beginPath();ctx.arc(q.x,q.y,r*.37,0,7);ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=Math.max(1,r*.1);ctx.beginPath();ctx.arc(q.x,q.y,r*.58,0,7);ctx.stroke()}
// body as faceted, compact armored coupe
const b=(x,y,z)=>carPoint(car,x,y,z),L=2.35,X=1.38;
fill3([b(-X,.38,-L),b(X,.38,-L),b(X,1.18,-L),b(-X,1.18,-L)],'#102638');
fill3([b(-X,.38,-L),b(-X,1.18,-L),b(-.95,1.62,.35),b(-1.3,1.15,L)],car.team==='blue'?'#168ac5':'#c44c26');
