else{const dx=ball.x-car.x,dz=ball.z-car.z,desired=Math.atan2(dx,dz);let delta=Math.atan2(Math.sin(desired-car.yaw),Math.cos(desired-car.yaw));turn=clamp(delta*2.8,-1,1);throttle=.84;if(Math.abs(delta)>2.3)throttle=-.4;boosting=car.boost>8&&Math.abs(delta)<.3&&hyp(dx,dz)>15;if(car.y<.2&&hyp(dx,dz)<11&&Math.random()<dt*.55)car.vy=8+Math.random()*3}
const speed=car.vx*forwardX+car.vz*forwardZ,steerScale=.6+Math.min(Math.abs(speed)/15,1);car.yaw+=turn*dt*(1.55+steerScale*.9)*(speed< -1?-1:1);const fx=Math.sin(car.yaw),fz=Math.cos(car.yaw);let accel=throttle*(boosting?35:23);car.vx+=fx*accel*dt;car.vz+=fz*accel*dt;if(boosting){car.boost=Math.max(0,car.boost-31*dt);for(let n=0;n<2;n++){const q=carPoint(car,rand(-.5,.5),.5,rand(-2.2,-2.8));if(Math.random()<.8)addParticle(...q,car.team==='blue'?'#54e7ff':'#ff964a',.48)}}else if(isPlayer&&car.y<.2)car.boost=Math.min(100,car.boost+1.6*dt);
